class MinStack:
    """A stack that reports its smallest value."""

    def __init__(self):
        self._head = None
        self._size = 0

    def push(self, value):
        minimum = value if self._head is None else min(self._head[1], value)
        self._head = (value, minimum, self._head)
        self._size += 1

    def pop(self):
        if self._head is None:
            raise IndexError("pop from empty stack")
        value, _, self._head = self._head
        self._size -= 1
        return value

    def top(self):
        if self._head is None:
            raise IndexError("top of empty stack")
        return self._head[0]

    def get_min(self):
        if self._head is None:
            raise ValueError("minimum of empty stack")
        return self._head[1]

    def __len__(self):
        return self._size

